function C:GoOut()
  if not coroutine.isyieldable() then spawn(C.GoOut, self) return end
  JineManager:Uncontrolable()
  AudioManager:PlaySeByType("SE_Odekake_zazaza", false)
  WebCamManager:GoOut()
  NgoEvent.DelaySkippable(2000)
  WindowManager:CloseApp("Webcam")
  WindowManager:CloseApp("GoOut")
  local TrainTime = nil
  if EventManager.nowEnding == "Ending_Ginga" then
    TrainTime = "Train_Ginga"
    WindowManager:NewWindow_2(TrainTime, true):Uncloseable()
    AudioManager:PlayBgmByType("BGM_Train", false)
    UniTask.Delay(13000, false, "Update", nil, false)
    WindowManager:CloseApp(TrainTime)
    return
  end
  TrainTime = (function(__v1) if __v1 == 0 then return "Train" end if __v1 == 1 then return "Train_twilight" end if true then return "Train_night" end end)(StatusManager:GetStatus("DayPart"))
  WindowManager:NewWindow_2(TrainTime, true)
  local cts = NEW("CancellationTokenSource", nil)
  self:ClickableAllScreen(true)
  EventManager.cover:OnPointerDownAsObservable():Subscribe(function(_)
    cts:Cancel()
  end):AddTo(self.compositeDisposable)
  local __ok2, __err = pcall(function()
    AudioManager:PlayBgmByType("BGM_Train", false)
    UniTask.Delay(13000, false, "Update", cts.Token, false)
    cts:Cancel()
    self:ClickableAllScreen(false)
    WindowManager:CloseApp(TrainTime)
  end)
  if not __ok2 then
    if not IS_CANCEL(__err) then error(__err, 0) end
    AudioManager:StopByType("BGM_Train")
    self:ClickableAllScreen(false)
    WindowManager:CloseApp(TrainTime)
  end
  local soundType = "BGM_mainloop_kenjo"
  local status = StatusManager:GetStatus("Follower")
  if status >= 10000 then
    soundType = "BGM_mainloop_normal"
  end
  if status >= 100000 then
    soundType = "BGM_mainloop_yami"
  end
  if StatusManager:GetStatus("DayIndex") >= 11 then
    soundType = "BGM_mainloop_middle"
  end
  if StatusManager:GetStatus("DayIndex") >= 20 then
    soundType = "BGM_mainloop_shuban"
  end
  if AudioManager ~= nil and (AudioManager.PlayingBgm.Value == nil or (AudioManager.PlayingBgm).Value.Sound.Id ~= TOSTR(soundType)) then
    AudioManager:PlayBgmByType(soundType, true)
  end
end

function C:BackFromOdekake()
  if not coroutine.isyieldable() then spawn(C.BackFromOdekake, self) return end
  repeat
    local __sw3 = Random.Range(0, 5)
    if __sw3 == 0 then
      JineManager:AddJineHistory_2("HangOut_LINE002")
    elseif __sw3 == 1 then
      JineManager:AddJineHistory_2("HangOut_LINE003")
    elseif __sw3 == 2 then
      JineManager:AddJineHistory_2("HangOut_LINE004")
    elseif __sw3 == 3 then
      JineManager:AddJineHistory_2("HangOut_LINE005")
    else
