    end
  until true
  NgoEvent.DelaySkippable(Constants.MIDDLE)
end

function C:NadeNade(eventAfter, isActiveAppJine)
  if not coroutine.isyieldable() then spawn(C.NadeNade, self, eventAfter, isActiveAppJine) return end
  if isActiveAppJine then
    WindowManager:NewWindow_2("Jine", true)
  end
  NgoEvent.DelaySkippable(Constants.FAST)
  spawn(function() TooltipManager:Show_2("Tooltip_nadenade") end)
  local ame = WindowManager:NewWindow_2("Webcam", true)
  ame:Uncloseable()
  local nadeCount = WindowManager:GetNakamiFromApp("Webcam"):GetComponent("App_Webcam").AmeHead:GetComponent("Amehead").NadeCount
  local firstValue = nadeCount.Value
  nadeCount:Where(function(v) return v == firstValue + 1 end):Subscribe(function(_)
    spawn(function() TooltipManager:Show_2("Tooltip_more") end)
  end):AddTo(self.compositeDisposable)
  nadeCount:Where(function(v) return v >= firstValue + 3 end):Take(1):Subscribe(function(_)
    AudioManager:PlaySeByType("SE_nadenade_2", false)
    TooltipManager:Hide(false)
    ame:Closeable()
    eventAfter()
  end):AddTo(self.compositeDisposable)
end

